-- Mark all profiled food items created by Cooking recipes. Nourishment applies
-- the configured stat multiplier to these items without changing duration.
ALTER TABLE `mod_homebrew_nourishment_profile`
  ADD COLUMN `cooked` TINYINT UNSIGNED NOT NULL DEFAULT 0 AFTER `grade`;

UPDATE `mod_homebrew_nourishment_profile` SET `cooked` = 0;
UPDATE `mod_homebrew_nourishment_profile`
SET `cooked` = 1
WHERE `recovery_kind` = 'food'
  AND `item_id` IN (
    724,733,787,1017,1082,2679,2680,2681,2683,2684,2685,2687,3220,3662,3663,3664,3665,3666,
    3726,3727,3728,3729,4457,4592,4593,5095,5472,5473,5474,5476,5477,5478,5479,5480,5525,
    5526,5527,6038,6290,6316,6887,6888,6890,8364,12209,12210,12212,12213,12214,12215,12216,
    12218,12224,13851,13927,13928,13929,13930,13931,13933,13934,13935,16766,17197,17198,17222,
    18045,18254,20074,20452,21023,22645,24105,27635,27636,27651,27657,27658,27659,27660,27661,
    27662,27663,27664,27665,27666,27667,30155,30816,31672,31673,33048,33052,33872,33924,34747,
    34749,34750,34751,34752,34755,34756,34757,34758,35565,42994,42995
